package com.dawnrise.academic.security.internal;
import jakarta.servlet.FilterChain;import jakarta.servlet.http.*;import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import org.springframework.security.core.context.SecurityContextHolder;import java.util.List;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class InternalServiceAuthenticationFilterTest {private InternalServiceAuthenticationFilter filter(){InternalServiceSecurityProperties p=new InternalServiceSecurityProperties();p.setApiKey("secret");p.setAllowedServiceNames(List.of("school-service"));return new InternalServiceAuthenticationFilter(p);}@Test void authenticatesAllowlistedSchoolService()throws Exception{MockHttpServletRequest request=new MockHttpServletRequest("GET","/internal/v1/organizations/1/notification-audience/GRADE/2");request.addHeader("X-Internal-Api-Key","secret");request.addHeader("X-Service-Name","school-service");MockHttpServletResponse response=new MockHttpServletResponse();FilterChain chain=mock(FilterChain.class);filter().doFilter(request,response,chain);verify(chain).doFilter(request,response);assertEquals("school-service",SecurityContextHolder.getContext().getAuthentication().getName());SecurityContextHolder.clearContext();}@Test void rejectsUnknownService()throws Exception{MockHttpServletRequest request=new MockHttpServletRequest("GET","/internal/v1/test");request.addHeader("X-Internal-Api-Key","secret");request.addHeader("X-Service-Name","browser");MockHttpServletResponse response=new MockHttpServletResponse();FilterChain chain=mock(FilterChain.class);filter().doFilter(request,response,chain);assertEquals(403,response.getStatus());verifyNoInteractions(chain);}}
